-- 385: Original BrillaPrep flashcards, batch flashcards-beta-001, part 5 of 5.
-- Curriculum-aligned revision content; not official WAEC or NaCCA examination material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_human_biology_07', 'deck_int_science_human_biology', 'Distinguish between arteries and veins.', 'Arteries carry blood away from the heart under high pressure and have thick, elastic, muscular walls; veins carry blood towards the heart under low pressure and have thinner walls with valves that prevent backflow.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_human_biology_08', 'deck_int_science_human_biology', 'What is homeostasis? Give one example.', 'The maintenance of a constant internal environment despite external changes — for example, the regulation of blood glucose by insulin, or temperature control through sweating and shivering.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_human_biology_09', 'deck_int_science_human_biology', 'What are the roles of sensory and motor neurones?', 'Sensory neurones carry impulses from receptors to the central nervous system; motor neurones carry impulses from the central nervous system to effectors (muscles and glands).', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_human_biology_10', 'deck_int_science_human_biology', 'Name the main classes of food nutrients and the role of each.', 'Carbohydrates supply energy; proteins are for growth and repair; fats provide concentrated energy and insulation; vitamins and minerals perform protective and regulatory roles; water is the transport medium, and roughage (fibre) keeps digestion healthy.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_core_trig_01', 'deck_core_math_trigonometry', 'State the three primary trigonometric ratios for a right-angled triangle.', 'sin θ = opposite/hypotenuse, cos θ = adjacent/hypotenuse, tan θ = opposite/adjacent (remembered as SOH CAH TOA).', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_core_trig_02', 'deck_core_math_trigonometry', 'What is the exact value of sin 30°?', '½', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_core_trig_03', 'deck_core_math_trigonometry', 'What is the exact value of cos 60°?', '½', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_core_trig_04', 'deck_core_math_trigonometry', 'What is the exact value of tan 45°?', '1', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_core_trig_05', 'deck_core_math_trigonometry', 'When do you use the sine rule, and what does it state?', 'a/sin A = b/sin B = c/sin C. Use it when a matching side–angle pair is known, for any triangle (not only right-angled ones).', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_core_trig_06', 'deck_core_math_trigonometry', 'When do you use the cosine rule, and what does it state?', 'a² = b² + c² − 2bc cos A. Use it when two sides and the included angle are known, or when all three sides are known.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_core_trig_07', 'deck_core_math_trigonometry', 'Write the formula for the area of a triangle given two sides and the included angle.', 'Area = ½ab sin C, where C is the angle between sides a and b.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_core_trig_08', 'deck_core_math_trigonometry', 'Define the angle of elevation.', 'The angle measured upward from the horizontal to the line of sight of an object above the observer.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_core_trig_09', 'deck_core_math_trigonometry', 'Define the angle of depression.', 'The angle measured downward from the horizontal to the line of sight of an object below the observer; it equals the angle of elevation from the object back to the observer (alternate angles).', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_core_trig_10', 'deck_core_math_trigonometry', 'A 10 m ladder leans against a wall and reaches 8 m up the wall. What angle does it make with the ground?', 'sin θ = 8/10 = 0.8, so θ = sin⁻¹(0.8) ≈ 53.1°.', NULL, 'Which ratio links opposite and hypotenuse?', 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_governance_01', 'deck_social_governance', 'What is democracy?', 'A system of government in which political power belongs to the people, who exercise it directly or through freely elected representatives chosen in periodic elections.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_governance_02', 'deck_social_governance', 'Name the three arms of government in Ghana and the role of each.', 'The Legislature (Parliament) makes laws; the Executive (the President and ministers) implements laws and runs the state; the Judiciary interprets the laws and administers justice.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_governance_03', 'deck_social_governance', 'What is the Constitution?', 'The supreme law of the land, which sets out the structure of government, the powers of state institutions and the fundamental rights of citizens; every other law must conform to it.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_governance_04', 'deck_social_governance', 'What is the rule of law?', 'The principle that everyone — citizens and leaders alike — is subject to and equal before the law, and that power is exercised according to known laws rather than arbitrary decisions.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_governance_05', 'deck_social_governance', 'What is the separation of powers?', 'The division of government power among the executive, legislature and judiciary so that no single arm becomes all-powerful; each arm checks the others (checks and balances).', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_governance_06', 'deck_social_governance', 'List three fundamental human rights guaranteed to Ghanaians.', 'Any three of: the right to life; personal liberty; freedom of speech and expression; freedom of association and assembly; equality before the law; freedom from discrimination.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_governance_07', 'deck_social_governance', 'List three responsibilities of a good citizen.', 'Any three of: obeying the laws of the land; paying taxes; voting in elections; protecting public property; taking part in community development; defending the country when called upon.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_governance_08', 'deck_social_governance', 'What makes an election free and fair?', 'Universal adult suffrage, a secret ballot, equal access for candidates, independent administration by the Electoral Commission, and transparent counting and declaration of results.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_governance_09', 'deck_social_governance', 'What is decentralisation in Ghana’s system of governance?', 'The transfer of power, functions and resources from central government to local assemblies — the Metropolitan, Municipal and District Assemblies — so that decisions are taken closer to the people.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_governance_10', 'deck_social_governance', 'What is the role of the Electoral Commission of Ghana?', 'It is the independent body responsible for conducting and supervising all public elections and referenda, compiling the voters’ register, and declaring results.', NULL, NULL, 2);
